type Access = { name: string; latitude: number; longitude: number; mileFromStart: number; note: string; segmentKind?: 'lake' | 'transition' | 'creek' };
type Spec = {
  id: string; riverId: string; name: string; reach: string; aliases: string[]; region: string;
  summary: string; statusText: string; distance: string; time: string; difficulty: 'easy' | 'moderate' | 'hard';
  risk: RouteSafetyProfile['riskLevel']; hazards: RouteSafetyProfile['hazards']; safety: string[];
  gauge: string; gaugeName: string; gaugeKind: 'direct' | 'proxy'; gaugeMetric?: 'discharge_cfs' | 'gage_height_ft';
  thresholdUrl: string; thresholdLabel: string; sourceUrl: string; sourceLabel: string; mapUrl: string;
  putIn: Access; takeOut: Access; access: Access[]; camping: string; campingClassification: 'none' | 'nearby_basecamp' | 'endpoint_campground';
  shuttle: string; permits: string; watchFor: string[]; image: string; imageLabel: string; imageCredit: string; imageTaken: string;
  season?: number[]; threshold?: { tooLow?: number; idealMin?: number };
  thresholdProvider?: SourceProvider; thresholdSourceStrength?: SourceStrength;
  thresholdEvidence?: string; thresholdEvidenceUrl?: string;
  scoreEligibility?: River['scoreEligibility'];
};

function makeRoute(spec: Spec): River {
  const hydrographUrl = `https://waterdata.usgs.gov/nwis/uv/?referred_module=sw&site_no=${spec.gauge}`;
  const detailUrl = `https://waterdata.usgs.gov/monitoring-location/USGS-${spec.gauge}/`;
  const scoreEligibility = spec.scoreEligibility ?? (scoredSeedskadeeIds.has(spec.id) ? 'scored' : 'planning');
  const statusText = scoreEligibility === 'scored' ? spec.statusText.replace('Planning-only', 'Scored minimum-only') : spec.statusText;
  const imageNote = spec.gaugeKind === 'proxy'
    ? 'Approved same-watershed context image; it is not presented as a photograph of this exact reach.'
    : 'Approved same-river context image; it is not presented as a photograph of every point in this reach.';
  const thresholdProvider = spec.thresholdProvider
    ?? (spec.thresholdUrl.includes('americanwhitewater.org') ? 'american_whitewater' : spec.thresholdUrl.includes('nps.gov') ? 'nps' : 'local');
  const thresholdSourceStrength = spec.thresholdSourceStrength ?? (scoreEligibility === 'scored' ? 'official' : thresholdProvider === 'american_whitewater' ? 'community' : 'mixed');
  const thresholdValue = spec.threshold
    ? [spec.threshold.tooLow != null ? `floor ${spec.threshold.tooLow}` : null, spec.threshold.idealMin != null ? `preferred cue ${spec.threshold.idealMin}` : null].filter(Boolean).join('; ')
    : 'No numeric cutoff claimed';
  const thresholdEvidenceUrl = spec.thresholdEvidenceUrl ?? spec.thresholdUrl;
  return {
    id: spec.id, slug: spec.id, riverId: spec.riverId, name: spec.name, reach: spec.reach, aliases: spec.aliases,
    state: 'Wyoming', region: spec.region, routeType: spec.difficulty === 'hard' && spec.hazards.includes('whitewater') ? 'whitewater' : 'recreational',
    summary: spec.summary, statusText, latitude: spec.putIn.latitude, longitude: spec.putIn.longitude,
    safetyProfile: { riskLevel: spec.risk, hazards: spec.hazards, safetyNotes: spec.safety, reviewStatus: 'reviewed' },
    gaugeSource: { id: `usgs-${spec.gauge}`, provider: 'usgs', siteId: spec.gauge, metric: spec.gaugeMetric ?? 'discharge_cfs', unit: spec.gaugeMetric === 'gage_height_ft' ? 'ft' : 'cfs', kind: spec.gaugeKind, siteName: spec.gaugeName, detailUrl, hydrographUrl },
    profile: {
      thresholdModel: 'minimum-only', ...(spec.threshold ?? {}), thresholdSource: { label: spec.thresholdLabel, url: spec.thresholdUrl, provider: thresholdProvider },
      thresholdSourceStrength, rainfallSensitivity: 'high', seasonMonths: spec.season ?? [5, 6, 7, 8, 9],
      seasonNotes: 'Plan for late spring through early fall only after checking the live gauge, weather, water temperature, wind, debris, and land-manager notices. Shoulder-season ice, snow, and cold water can make a nominally open launch unsafe.',
      difficulty: spec.difficulty, difficultyNotes: 'Published difficulty is a planning classification, not a safety guarantee. Scout current hazards and keep a conservative turnaround rule.',
      confidenceNotes: 'Route endpoints, mileage/time, and operating constraints are supported by the named official agency or park source. Gauge and flow fields are planning inputs only; local inspection and current closure/access checks control the launch decision.',
    },
    putIn: { name: spec.putIn.name, latitude: spec.putIn.latitude, longitude: spec.putIn.longitude },
    takeOut: { name: spec.takeOut.name, latitude: spec.takeOut.latitude, longitude: spec.takeOut.longitude },
    accessPoints: spec.access.map((a) => ({ id: `${spec.id}-${a.name.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`, name: a.name, latitude: a.latitude, longitude: a.longitude, mileFromStart: a.mileFromStart, segmentKind: a.segmentKind ?? 'transition', note: a.note })),
    logistics: { distanceLabel: spec.distance, estimatedPaddleTime: spec.time, shuttle: spec.shuttle, permits: spec.permits, camping: spec.camping, campingClassification: spec.campingClassification, summary: spec.summary, accessCaveats: ['Use only the named public or land-manager access; a nearby shoreline is not proof of a legal launch.', 'Confirm seasonal gates, parking, fees, permits, AIS inspection, carry path, and take-out status immediately before the trip.', 'Private banks and easements may constrain landing, scouting, camping, or portage; remain within the authorized corridor.'], watchFor: spec.watchFor },
    evidenceNotes: [
      { label: 'Official route corridor', value: `${spec.reach}; ${spec.distance}`, note: `${spec.sourceLabel} identifies the access pair and operational character.`, sourceUrl: spec.sourceUrl },
      { label: spec.gaugeKind === 'direct' ? 'Direct live gauge' : 'Defensible proxy gauge', value: `USGS ${spec.gauge} — ${spec.gaugeName}`, note: spec.gaugeKind === 'direct' ? 'Gauge is on the named river corridor.' : 'Gauge is upstream or downstream in the same regulated river system; it cannot substitute for a local scout or dam-release notice.', sourceUrl: detailUrl },
      { label: 'Threshold posture', value: spec.threshold ? (scoreEligibility === 'scored' ? `Gauge-linked minimum-only scoring range (${thresholdValue})` : `Minimum-only planning cue (${thresholdValue})`) : 'Minimum-only planning model with no numeric cutoff', note: spec.thresholdEvidence ?? (scoreEligibility === 'scored' ? 'USFWS publishes a 700 cfs refuge operating context and an 800 cfs summer minimum for this regulated Green River corridor; Paddle Today uses 700 cfs as a conservative lower planning floor and 800 cfs as a preferred cue. These are not safety guarantees; hazards, closures, wind, debris, and local inspection override the score.' : 'No live scoring is justified from the available route-specific evidence; the model is intentionally planning-only.'), sourceUrl: thresholdEvidenceUrl },
      { label: 'Public access control', value: `${spec.putIn.name} to ${spec.takeOut.name}`, note: 'Named agency/park access points are retained, including any intentional parking or campground offset from the shoreline.', sourceUrl: spec.mapUrl },
      { label: 'Safety and land management', value: 'PFD, AIS, water temperature, current hazards, and current closures govern the decision', note: 'Review current agency rules, dam/release notices, wind, debris, and private-bank restrictions before launching.', sourceUrl: spec.sourceUrl },
      { label: 'Camping classification', value: spec.campingClassification, note: spec.camping, sourceUrl: spec.sourceUrl },
      { label: 'Image decision', value: spec.imageLabel, note: imageNote, sourceUrl: spec.image },
      { label: 'Overlap decision', value: 'Retained as a distinct access-to-access card', note: 'Adjacent cards have different launch/take-out pairs, operational boundaries, difficulty, or trip length; no duplicate corridor was found in the Wyoming baseline.', sourceUrl: spec.sourceUrl },
    ],
    sourceLinks: [
      { label: spec.sourceLabel, url: spec.sourceUrl, provider: spec.sourceUrl.includes('nps.gov') ? 'nps' : 'local' },
      { label: spec.thresholdLabel, url: spec.thresholdUrl, provider: thresholdProvider },
      ...(spec.thresholdEvidenceUrl && spec.thresholdEvidenceUrl !== spec.thresholdUrl ? [{ label: 'Secondary threshold context', url: spec.thresholdEvidenceUrl, provider: 'local' as const }] : []),
      { label: 'Official access/map control', url: spec.mapUrl, provider: spec.mapUrl.includes('nps.gov') ? 'nps' : 'local' },
      { label: `USGS ${spec.gauge} monitoring location`, url: detailUrl, provider: 'usgs' },
      { label: `USGS ${spec.gauge} current conditions`, url: hydrographUrl, provider: 'usgs' },
      { label: spec.imageLabel, url: spec.image, provider: spec.image.includes('nps.gov') ? 'nps' : 'manual' },
      { label: 'Wyoming boating and watercraft rules', url: boatingRules, provider: 'local' },
    ],
    scoreEligibility, scoreEligibilityReason: scoreEligibility === 'planning' && spec.gaugeKind === 'proxy' ? 'proxy_gauge' : undefined,
  };
}

