const commonSnakeSafety = ['Wear a properly fitted PFD; the Snake is cold, braided, and debris-prone even on scenic sections.', 'Grand Teton requires a current boat permit and AIS compliance; closures, seasonal launch hours, and mandatory take-outs override this card.', 'Stay in the channel and do not land on private banks or unmarked islands; carry emergency communication because cell coverage is inconsistent.'];
